function validate([picture, target]) {
  if (picture.length < 1 || picture.length > 200) return 'picture needs 1 to 200 rows.';
  const n = picture[0].length;
  if (n < 1 || n > 200) return 'Each row needs 1 to 200 cells.';
  if (picture.some(row => row.length !== n)) return 'Every row must have the same length.';
  if (picture.some(row => row.some(cell => cell !== 'W' && cell !== 'B'))) return "Each cell is 'W' or 'B'.";
  if (!Number.isInteger(target) || target < 1 || target > Math.min(picture.length, n)) return 'target is between 1 and min(m, n).';
  return null;
}

