function findBlackPixel(picture, target) {
  const cols = picture[0].length;
  const colCount = new Array(cols).fill(0);
  const patterns = new Map();
  for (const row of picture) {
    let black = 0;
    for (let c = 0; c < cols; c++) {
      if (row[c] === 'B') {
        black++;
        colCount[c]++;
      }
    }
    if (black === target) {
      const key = row.join('');
      patterns.set(key, (patterns.get(key) || 0) + 1);
    }
  }
  let lonely = 0;
  for (const [key, count] of patterns) {
    if (count !== target) {
      continue;
    }
    for (let c = 0; c < cols; c++) {
      if (key[c] === 'B' && colCount[c] === target) {
        lonely += target;
      }
    }
  }
  return lonely;
}

