function findBlackPixel(picture, target) {
  // Test both rules directly for every black cell.
  const m = picture.length, n = picture[0].length;
  let total = 0;
  for (let r = 0; r < m; r++) {
    for (let c = 0; c < n; c++) {
      if (picture[r][c] !== 'B') continue;
      const inRow = picture[r].filter(cell => cell === 'B').length;
      const inCol = picture.filter(row => row[c] === 'B').length;
      if (inRow !== target || inCol !== target) continue;
      let same = true;
      for (let k = 0; k < m && same; k++) {
        if (picture[k][c] !== 'B') continue;
        for (let j = 0; j < n; j++) if (picture[k][j] !== picture[r][j]) { same = false; break; }
      }
      if (same) total++;
    }
  }
  return total;
}

