function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const large = size === 'large';
  const m = large ? 60 + pick(41) : 1 + pick(6);
  const n = large ? 60 + pick(41) : 1 + pick(6);
  const target = 1 + pick(Math.min(m, n, large ? 10 : 6));
  const unused = Array.from({ length: n }, (_, c) => c);
  for (let i = n - 1; i > 0; i--) { const j = pick(i + 1); [unused[i], unused[j]] = [unused[j], unused[i]]; }
  const rows = [];
  // A row with exactly k black cells, preferring columns no group has used yet.
  const rowWith = (k, fresh) => {
    const row = new Array(n).fill('W');
    let placed = 0;
    while (placed < k) {
      const c = fresh && unused.length && rand() < 0.85 ? unused.pop() : pick(n);
      if (row[c] === 'W') { row[c] = 'B'; placed++; }
    }
    return row;
  };
  while (rows.length < m) {
    const roll = rand();
    if (roll < 0.55 && target <= n) {
      // A group of identical rows: target copies make lonely cells, one more or fewer breaks them.
      const row = rowWith(target, true);
      const copies = Math.min(m - rows.length, Math.max(1, target + (rand() < 0.75 ? 0 : rand() < 0.5 ? 1 : -1)));
      for (let k = 0; k < copies; k++) rows.push([...row]);
    } else if (roll < 0.8) {
      rows.push(rowWith(Math.min(n, target), false));
    } else {
      const density = large ? 0.03 : rand();
      rows.push(Array.from({ length: n }, () => (rand() < density ? 'B' : 'W')));
    }
  }
  for (let i = m - 1; i > 0; i--) { const j = pick(i + 1); [rows[i], rows[j]] = [rows[j], rows[i]]; }
  return [rows, target];
}
